// Programmatic focus raises the soft keyboard on touch devices (#1067).
function touchPrimary() {
  return !!window.matchMedia?.('(pointer: coarse)').matches;
}

s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, t, u) => (
  isSafeHref(u) ? `<a href="${u}" target="_blank" rel="noopener noreferrer">${t}</a>` : t
));

